import json
import csv

# Read event.json
with open('json/event.json', 'r') as f:
    event_data = json.load(f)

events = {e['event_id']: e['event_name'] for e in event_data['records']}

# Read budget.csv
budgets = {}
with open('csv/budget.csv', 'r') as f:
    reader = csv.DictReader(f)
    for row in reader:
        event_id = row['link_to_event']
        spent = float(row['spent'])
        if event_id not in budgets:
            budgets[event_id] = 0
        budgets[event_id] += spent

# Find minimum cost and all events with that cost
min_cost = float('inf')
for event_id, cost in budgets.items():
    if cost < min_cost:
        min_cost = cost

# Find all events with minimum cost
min_events = []
for event_id, cost in budgets.items():
    if cost == min_cost:
        min_events.append((events.get(event_id, 'Unknown'), cost))

# Also include events without any budget (0.0)
for event_id, event_name in events.items():
    if event_id not in budgets:
        if 0.0 < min_cost:
            min_events = [(event_name, 0.0)]
            min_cost = 0.0
        elif 0.0 == min_cost:
            min_events.append((event_name, 0.0))

print(f"Minimum cost: {min_cost}")
print(f"\nEvents with minimum cost ({len(min_events)} events):")
for name, cost in sorted(min_events, key=lambda x: x[0]):
    print(f"{name}: {cost}")

